def match_union(inp, col):
 seed=[(r,c) for r,row in enumerate(inp) for c,v in enumerate(row) if v==col]
 H,W=len(inp),len(inp[0]); candidates=[]
 for dr in range(-H,H):
  for dc in range(-W,W):
   pts=[(r+dr,c+dc) for r,c in seed]
   if all(0<=r<H and 0<=c<W and inp[r][c]==0 for r,c in pts): candidates.append((dr,dc))
 union={(r+dr,c+dc) for dr,dc in candidates for r,c in seed}
 return seed,candidates,union
